message.content:
{
  "css": ".search-unit {
  width: 100%;
}

.search-label {
  display: block;
  font-size: 14px;
  font-weight: 500;
  color: #283548;
  margin-bottom: 8px;
  line-height: 1.5;
}

.search-surface {
  display: flex;
  align-items: center;
  min-height: 46px;
  background-color: #fff;
  border-radius: 12px;
  padding: 0 16px;
  gap: 12px;
}

.search-surface img {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  object-fit: contain;
  opacity: 0.5;
}

.search-surface input {
  flex: 1;
  min-width: 0;
  background-color: transparent;
  border: none;
  padding: 0;
  font-size: 14px;
  font-weight: 500;
  color: #283548;
  outline: none;
}

.search-surface input::placeholder {
  color: #566273;
  opacity: 1;
}"
}
